@startuml

class Customer {
  + name: string
  + surname: string
  + age: int
  + address: string
  + profession: string
}

class Subscription {
  + type: string
}

class BaseService {
  + name: string
}

class AdditionalService {
  + name: string
}

class WorkoutPlan {
  + frequency: int
}

class Exercise {
  + name: string
  + repetitions: int
}

class MedicalCheck {
  + weight: float
  + bodyFat: float
  + electrocardiogram: string
  + restingHeartbeat: int
  + stressHeartbeat: int
}

class MedicalStaff {}

class Gym {
  + computeMonthlyBalance()
  + computeYearlyBalance()
  + sendArrearsReminder()
  + sendMedicalCheckReminder()
}

Subscription "1" -- "*" Customer : has
BaseService "1" -- "*" Customer : includedIn
AdditionalService "0..*" -- "*" Customer : requestedBy
Customer "1" -- "0..1" WorkoutPlan : follows
WorkoutPlan "1" -- "*" Exercise : defines
Customer "0..1" -- "0..1" MedicalStaff : assistedBy
Customer "1" -- "*" MedicalCheck : undergoes
Gym "1" -- "*" Customer : manages

@enduml

